            _ = visitor.visit(order.source_index, with_code_splitting, with_scb);
        }
},
}
},
}
        const parts_in_chunk_order = try ctx.allocator().alloc(PartRange, (visitor.part_ranges.items.len + visitor.parts_prefix.items.len));
        _ = bun.concat(PartRange, parts_in_chunk_order, (&.{ visitor.parts_prefix.items, visitor.part_ranges.items }));
        chunk.content.javascript.files_in_chunk_order = visitor.files.items;
        chunk.content.javascript.parts_in_chunk_in_order = parts_in_chunk_order;
}
